import java.util.Set;

record Claims(
        String issuer,
        String audience,
        long expiresAt,
        long notBefore,
        Set<String> scopes) {
}

public class Main {
    static boolean allowed(Claims claims, long now) {
        return claims.issuer().equals("https://id.example")
                && claims.audience().equals("orders")
                && now < claims.expiresAt()
                && now >= claims.notBefore()
                && claims.scopes().contains("orders:read");
    }

    public static void main(String[] args) {
        Claims claims = new Claims(
                "https://id.example", "orders", 1100, 900,
                Set.of("profile", "orders:read"));
        System.out.println(allowed(claims, 1000));
    }
}

